using namespace civ5;using namespace civ5::runtime;
namespace {
void check(bool v,const char *why){if(!v)throw std::runtime_error(why);}
auto &named(auto &rows,std::string_view key){for(auto &r:rows)if(r.name&&key==r.name)return r;throw std::runtime_error("Tourism/influence fixture required field absent");}
auto &culture(LiveSessionState &s){return named(s.world.all_players->players.at(0).trade_culture.blocks,"player_culture");}
auto &influence(LiveSessionState &s){return named(culture(s).arrays,"m_aiCulturalInfluence").values;}
void set_met(LiveSessionState &s,std::int64_t from,std::int64_t to,bool v){named(s.world.teams->teams.at(from).arrays,"has_met").values.at(to)=v;auto &met=s.player_research.teams.at(from).met;if(v)met.insert(to);else met.erase(to);}
void set_lifetime(LiveSessionState &s,std::int64_t p,std::int64_t value){named(s.world.all_players->players.at(p).core.fields,"m_iJONSCultureEverGenerated").values[0]=value;}
void blocked(const auto &q,std::string_view why){check(!q.calculated,"Unknown native input supplied a result");check(q.blocker.find(why)!=std::string::npos,(q.blocker+"; wanted "+std::string(why)).c_str());}
}
