 auto selected=ui::bootstrap_selected_bnw_preview(argv[1],argv[2],0);check(static_cast<bool>(selected.preview),"Selected preview absent");auto &host=*selected.preview.host;const auto lease=host.session().read_state_lease();const auto &original=*lease;const auto generation=host.session().state_generation();const auto identity=host.identity();const auto tourism_rules=BnwGrandWorldAverageRules::load(host.database());const auto influence_rules=BnwCultureInfluenceRules::load(host.database());const auto game_rng=original.random.gameplay.state(),map_rng=original.random.map.state();
