 for(int i=0;i<3;++i){auto w=original;const auto city=w.cities.players[0].cities.begin()->first;if(i==0)++w.cities.players[0].cities[city].real_buildings.begin()->second;if(i==1)++named(w.world.all_players->players[0].cities.header.fields,"last_index").value;if(i==2)w.world.leagues.version.reset();const auto q=quote_bnw_player_tourism(w,tourism_rules,identity,0);blocked(q,i==0?"building count stale":i==1?"FLTA inventory":"GameLeagues Read inventory");check(!q.total,"Blocked player tourism exposed a total");}
