 for(const auto threshold:influence_rules.thresholds())for(int delta:{-1,0,1}){auto w=original;set_met(w,1,0,true);set_lifetime(w,1,100);influence(w)[1]=threshold+delta;const auto q=quote_bnw_culture_influence_level(w,influence_rules,identity,0,1);check(q.calculated&&q.foreign_met&&q.influence==threshold+delta&&q.lifetime_culture==100&&q.percent==threshold+delta&&q.level==expected_level(threshold+delta),q.blocker.c_str());const auto c=quote_bnw_num_civs_influential_on(w,influence_rules,identity,0);check(c.calculated&&c.count==(*q.level>=4?1:0)&&c.foreigners.size()==1,"Influential count threshold/filter differs");}
 for(std::int32_t lifetime:{0,-1}){auto w=original;set_met(w,1,0,true);set_lifetime(w,1,lifetime);influence(w)[1]=INT32_MAX;const auto q=quote_bnw_culture_influence_level(w,influence_rules,identity,0,1);check(q.calculated&&q.percent==0&&q.level==expected_level(0),"Nonpositive culture evaluated forbidden overflow multiplication");}
 {auto w=original;set_met(w,1,0,true);set_lifetime(w,1,3);influence(w)[1]=2;const auto q=quote_bnw_culture_influence_level(w,influence_rules,identity,0,1);check(q.calculated&&q.percent==66&&q.level==expected_level(66),"Native influence integer division was rounded");}
